const artwork={minecraft:'https://www.minecraft.net/content/dam/minecraftnet/games/minecraft/key-art/Global-Header_Image-Tile_MC-Java-Bedrock_570x321.jpg',fortnite:'https://cdn2.unrealengine.com/en-fn-og-42-10-c1sx-egs-launcher-blade-2560x1440-2560x1440-319ff81b274e.jpg',valorant:'https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/083baed63d306ee9ba41df4971ac0f6bb0222032-1920x1080.jpg',gta:'https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/3240220/header.jpg',fc:'https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/3405690/7bee4fc257ccc11a9496f0c19c553cccfb9fafa9/capsule_616x353_alt_assets_3.jpg'};
const games=[['Minecraft','OPEN WORLD','minecraft'],['Fortnite','BATTLE ROYALE','fortnite'],['Valorant','TACTICAL FPS','valorant'],['GTA V','ACTION / ADVENTURE','gta'],['EA Sports FC','FOOTBALL','fc']];
const videos=[{title:'One round. Five opponents. No pressure.',game:'Valorant',image:'valorant',views:'12.8K',date:'Sep 12, 2026',length:'12:48'},{title:'Building something bigger. One block at a time.',game:'Minecraft',image:'minecraft',views:'8.4K',date:'Sep 08, 2026',length:'18:32'},{title:'The final circle had other plans…',game:'Fortnite',image:'fortnite',views:'16.2K',date:'Sep 04, 2026',length:'10:24'}];
document.querySelector('#game-grid').innerHTML=games.map(([name,category,image])=>`<article class="game-card"><img src="${artwork[image]}" alt="${name} game artwork" loading="lazy"><div class="game-info"><small>${category}</small><h3>${name.toUpperCase()}</h3><button data-game="${name}">View Content <span>↗</span></button></div></article>`).join('');
function renderVideos(filter){const shown=filter?videos.filter(v=>v.game===filter):videos;document.querySelector('#video-grid').innerHTML=shown.map(v=>`<article class="video-card"><button class="thumbnail" data-video="${v.game}" aria-label="Preview ${v.title}"><img src="${artwork[v.image]}" alt="${v.game} gameplay artwork" loading="lazy"><span class="play">▷</span><span class="duration">${v.length}</span></button><div class="video-info"><span class="category">${v.game.toUpperCase()}</span><h3>${v.title}</h3><div class="video-meta"><span>◉ ${v.views} views</span><span>${v.date}</span></div></div></article>`).join('');document.querySelector('#empty-state').hidden=shown.length>0;document.querySelector('#filter-label').textContent=filter?filter.toUpperCase()+' CONTENT':'FEATURED MOMENTS'}renderVideos();
const icons={PC:'<rect x="6" y="2" width="12" height="20" rx="2"/><circle cx="12" cy="9" r="3"/><path d="M10 18h4"/>',Monitor:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M12 17v4m-5 0h10"/>',Keyboard:'<rect x="1" y="6" width="22" height="12" rx="2"/><path d="M4 10h1m3 0h1m3 0h1m3 0h1m3 0h1M4 14h1m3 0h8m3 0h1"/>',Mouse:'<rect x="6" y="2" width="12" height="20" rx="6"/><path d="M12 2v7"/>',Headset:'<path d="M4 14v-3a8 8 0 0 1 16 0v3"/><rect x="2" y="12" width="5" height="8" rx="2"/><rect x="17" y="12" width="5" height="8" rx="2"/>',Controller:'<path d="M7 7h10c3 0 6 10 4 12s-5-3-7-3h-4c-2 0-5 5-7 3S4 7 7 7Z"/><path d="M8 10v5m-2.5-2.5h5M16 11h.01M18 14h.01"/>'};
const svg=p=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`;
document.querySelector('#setup-grid').innerHTML=Object.entries(icons).map(([name,path],i)=>`<article class="setup-card"><div class="setup-icon">${svg(path)}</div><h3>${name==='PC'?'Gaming PC':name}</h3><p>${['THE POWERHOUSE','EVERY FRAME COUNTS','BUILT FOR PRECISION','MAKE EVERY MOVE','HEAR EVERYTHING','TAKE CONTROL'][i]}</p></article>`).join('');
const socialIcons={YouTube:'<rect x="2" y="5" width="20" height="14" rx="4"/><path d="m10 9 5 3-5 3Z"/>',Twitch:'<path d="M4 2h18v14l-5 5h-5l-4 3v-3H3V6ZM9 21v-5H6V5h13v10l-4 3h-3Z"/><path d="M11 7v5m5-5v5"/>',TikTok:'<path d="M14 3v13a5 5 0 1 1-5-5v4a2 2 0 1 0 2 2V3h3c1 3 3 5 6 5v4c-3 0-5-2-6-3"/>',Instagram:'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><path d="M17.5 6.5h.01"/>',Discord:'<path d="m8 5-3 1-3 12 5 2 2-3m6 0 2 3 5-2-3-12-3-1M6 16c4 2 8 2 12 0M8 6h8"/><circle cx="8" cy="12" r="1"/><circle cx="16" cy="12" r="1"/>'};
document.querySelector('#social-grid').innerHTML=Object.entries(socialIcons).map(([name,path])=>`<button class="social-card" data-social="${name}">${svg(path)}<span><strong>${name}</strong><small>${name==='Discord'?'Join the squad':'@GMG_ALEJO'}</small></span><span>↗</span></button>`).join('');document.querySelector('#footer-socials').innerHTML=Object.entries(socialIcons).map(([name,path])=>`<button data-social="${name}" aria-label="${name}">${svg(path)}</button>`).join('');
const dialog=document.querySelector('dialog');function showDialog(title,description,label){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-description').textContent=description;document.querySelector('#dialog-label').textContent=label;dialog.showModal()}
document.addEventListener('click',e=>{const game=e.target.closest('[data-game]');if(game){renderVideos(game.dataset.game);document.querySelector('#videos').scrollIntoView({behavior:'smooth'})}const video=e.target.closest('[data-video]');if(video){const item=videos.find(v=>v.game===video.dataset.video);showDialog(item.title,'This is a sample highlight for the site preview. The official GMG_ALEJO video will be available here when its link is added.','VIDEO PREVIEW · '+item.game.toUpperCase())}const social=e.target.closest('[data-social]');if(social)showDialog('GMG_ALEJO ON '+social.dataset.social.toUpperCase(),'The official '+social.dataset.social+' profile link is coming soon. Check back to connect with the squad.','JOIN THE COMMUNITY');if(e.target.closest('.dialog-close,.dialog-dismiss'))dialog.close()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
for(const id of ['reset-filter','show-all'])document.getElementById(id).addEventListener('click',()=>renderVideos());const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=document.querySelector('header nav').classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰'});document.querySelectorAll('header nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('header nav').classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}));
const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){document.querySelectorAll('header nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id))}})},{rootMargin:'-20% 0px -50% 0px'});document.querySelectorAll('main section[id]').forEach(s=>observer.observe(s));if(!matchMedia('(prefers-reduced-motion: reduce)').matches){let waiting=false;window.addEventListener('scroll',()=>{if(!waiting){requestAnimationFrame(()=>{if(scrollY<innerHeight)document.querySelector('.hero-art').style.transform=`translateY(${scrollY*.16}px) scale(1.04)`;waiting=false});waiting=true}},{passive:true})}

